def words(s):
    return re.findall(r"[a-z0-9\-]+", s.lower())


def main():
    wb = {json.loads(l)["id"]: json.loads(l) for l in open(HERE / "workbook_items.jsonl", encoding="utf-8")}
    ex = json.loads(open(HERE / "contrast.jsonl", encoding="utf-8").readline())
    rows = [ex]
    for i, (A, B, Bm, C, Ct, N, W) in ITEMS.items():
        rows.append({"id": i, "source_arxiv": wb[i]["source_arxiv"], "A": A, "B": B, "B_min": Bm, "C": C,
                     "C_type": wb[i]["C_type"], "C_tilde": Ct, "narrower": N, "broader": W,
                     "length_flipped": len(words(W)) > len(words(N)), "author": "Claude (AI-written; declared)",
                     "second_reader_agrees": None})
    with open(HERE / "contrast.jsonl", "w", encoding="utf-8") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    print(len(rows) - 1, "items written")


if __name__ == "__main__":
    main()
